const taskWakeHealth = `-- name: TaskWakeHealth :one
SELECT (count(*) FILTER (WHERE disposition IS NULL))::bigint AS pending,
 (count(*) FILTER (WHERE disposition IS NULL AND attempts>0))::bigint AS failing,
 min(next_attempt_at) FILTER (WHERE disposition IS NULL AND next_attempt_at<=now())::timestamptz AS oldest_due_at
FROM task_wake
`

type TaskWakeHealthRow struct {
	Pending     int64
	Failing     int64
	OldestDueAt pgtype.Timestamptz
}

func (q *Queries) TaskWakeHealth(ctx context.Context) (TaskWakeHealthRow, error) {
	row := q.db.QueryRow(ctx, taskWakeHealth)
	var i TaskWakeHealthRow
	err := row.Scan(&i.Pending, &i.Failing, &i.OldestDueAt)
	return i, err
}

